"""PSLE-style items for sci-cycles-water-states (file sci-water-states.json), all tiers (round sci-fill-water-states-2026-11-20)."""
from fillkit import add, table, lint
from figs_heat import thermometer
from figs_wstates import states, curve, glass, kettle, pot_lid

SUB, FILE = "sci-cycles-water-states", "sci-water-states.json"
CS, RD, FT = "sci-pat-change-of-state", "sci-pat-read-data", "sci-pat-fair-test-design"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
D = "°C"
ST = lambda m, cap="Three states of water": (lambda: states(m, cap))
GL = lambda: glass()
KE = lambda: kettle()
PL = lambda: pot_lid()
CV = lambda: curve([(0, -10), (2, 0), (6, 0), (12, 100), (20, 100), (22, 112)], [("A", 1, -10, 8, -10), ("B", 4, 0, 0, -9), ("C", 9, 50, -13, 0), ("D", 16, 100, 0, -9), ("E", 21, 106, 14, 6)], caption="Heating ice in a beaker")
CC = lambda: curve([(0, 80), (8, 0), (18, 0), (24, -12)], [("P", 4, 40, 13, 0), ("Q", 13, 0, 0, -9), ("R", 21, -6, 12, -4)], caption="Cooling water in a freezer", ymin=-20, ymax=100)
WX = lambda: curve([(0, 30), (3, 60), (8, 60), (12, 90)], [], caption="Heating solid wax", ymin=0, ymax=100, xmax=12, xstep=2)
T1 = lambda: table(["Substance", "Melting point (" + D + ")", "Boiling point (" + D + ")"], [["P", "-20", "80"], ["Q", "40", "200"], ["R", "-50", "-10"], ["S", "80", "300"]], [90, 140, 140], "Melting and boiling points")
T2 = lambda: table(["Substance", "Melting point (" + D + ")", "Boiling point (" + D + ")"], [["P", "-115", "78"], ["Q", "-39", "357"], ["R", "1535", "2750"], ["S", "-219", "-183"]], [90, 140, 140], "Melting and boiling points")
T3 = lambda: table(["Form of water", "Fixed shape?", "Fixed volume?"], [["X", "Yes", "Yes"], ["Y", "No", "Yes"], ["Z", "No", "No"]], [110, 110, 110], "Water in three forms")
TH100 = lambda: thermometer(100, lo=0, hi=120, major=20, minor=10, caption="A thermometer")

# ---------------- basic ----------------
q("ws-001", B, 1, CS, "Which of the following is water in its solid state?", "A hailstone", [W("A raindrop", "wrong-state", "A raindrop is liquid water."), W("A puddle", "wrong-state", "A puddle is liquid water."), W("Water vapour in the air", "wrong-state", "Water vapour is the gas state.")], ["A hailstone is a lump of ice, which is solid water."], None)
q("ws-002", B, 1, CS, "Which statement about water in the gas state is correct?", "It cannot be seen and has no fixed shape", [W("It has a fixed shape and can be seen easily", "wrong-idea", "Water vapour is invisible and has no shape of its own."), W("It can be seen and has a fixed volume always", "wrong-idea", "Water vapour cannot be seen and it spreads out."), W("It has a fixed shape and a fixed volume", "wrong-idea", "That describes a solid, such as ice.")], ["Water vapour is invisible and spreads out to fill the space it is in."], None)
q("ws-003", B, 1, CS, "Which state of water keeps its own shape?", "Ice", [W("Liquid water", "wrong-state", "Liquid water takes the shape of its container."), W("Water vapour", "wrong-state", "Water vapour spreads out in any space."), W("Both liquid water and water vapour", "wrong-state", "Neither of these keeps its own shape.")], ["Only the solid state, ice, has a fixed shape."], None)
q("ws-004", B, 1, CS, "Which state of water takes the shape of its container but keeps the same volume?", "Liquid water", [W("Ice", "wrong-state", "Ice keeps its own shape."), W("Water vapour", "wrong-state", "Water vapour also changes its volume to fill the space."), W("All three states of water", "wrong-state", "Ice does not take the shape of its container.")], ["A liquid can flow into the shape of a container, and its volume stays the same."], None)
q("ws-005", B, 2, CS, "Which letter in the diagram shows ice changing into water?", "P", [W("Q", "mixed-up", "Q is water changing into ice, which is freezing."), W("R", "mixed-up", "R is water changing into water vapour."), W("S", "mixed-up", "S is water vapour changing into water.")], ["Ice to water is melting, which is P."], ST("A"))
q("ws-006", B, 2, CS, "Which letter in the diagram shows condensation?", "S", [W("P", "mixed-up", "P is melting."), W("Q", "mixed-up", "Q is freezing."), W("R", "mixed-up", "R is water changing into a gas, the opposite of condensation.")], ["Condensation is water vapour changing into liquid water, which is S."], ST("A"))
q("ws-007", B, 2, CS, "What is the change from liquid water to ice called?", "Freezing", [W("Melting", "mixed-up", "Melting is ice changing into water."), W("Boiling", "mixed-up", "Boiling is water changing into a gas."), W("Condensation", "mixed-up", "Condensation is a gas changing into a liquid.")], ["Liquid water changes to ice when it freezes."], None)
q("ws-008", B, 2, CS, "What is the change from water vapour to liquid water called?", "Condensation", [W("Evaporation or boiling", "mixed-up", "Evaporation is liquid water changing into water vapour."), W("Freezing", "mixed-up", "Freezing is water changing into ice."), W("Melting", "mixed-up", "Melting is ice changing into water.")], ["A gas changing to a liquid is condensation."], None)
q("ws-009", B, 3, CS, "At which temperature does pure ice melt?", "0 " + D, [W("100 " + D, "mixed-up", "100 " + D + " is the boiling point of water."), W("37 " + D, "wrong-reading", "37 " + D + " is the temperature of a healthy body."), W("-10 " + D, "wrong-reading", "Ice that is already melting is not this cold.")], ["Ice melts at 0 " + D + "."], None)
q("ws-010", B, 3, CS, "At which temperature does pure water boil at sea level?", "100 " + D, [W("0 " + D, "mixed-up", "0 " + D + " is the melting point of ice."), W("90 " + D, "wrong-reading", "Water is not boiling yet at 90 " + D + "."), W("10 " + D, "wrong-reading", "This is a cold temperature.")], ["Water boils at 100 " + D + "."], None)
q("ws-011", B, 2, CS, "Ice cubes on a plate in a warm room turn into water. What happens to the ice?", "It gains heat and melts", [W("It loses heat and melts", "reversed", "Melting needs heat to be gained."), W("It gains heat and freezes", "mixed-up", "Freezing is the change from water to ice."), W("It loses heat and freezes", "reversed", "The ice is turning into water, not the other way round.")], ["The ice takes in heat from the warm room and melts."], None)
q("ws-012", B, 2, CS, "Droplets of water form on the outside of a glass of iced water. Where does the water come from?", "Water vapour in the air", [W("Water that leaks through the glass", "wrong-idea", "Glass has no holes for water to pass through."), W("Ice that melts and flows out of the glass", "wrong-idea", "The glass is not leaking."), W("The glass itself, which makes water when cold", "wrong-idea", "A glass cannot make water.")], ["Water vapour in the air touches the cold glass and condenses."], GL)
q("ws-013", B, 2, CS, "A puddle on a concrete floor slowly disappears on a sunny day. What has happened to the water?", "It has changed into water vapour in the air", [W("It has frozen into a thin sheet of ice on the floor", "wrong-idea", "The Sun makes things warm, so ice would not form."), W("It has soaked down into the concrete floor", "wrong-idea", "Concrete floors do not soak up this much water."), W("It has been used up and is gone for good", "wrong-idea", "Water does not disappear. It changes state.")], ["The water gains heat from the Sun and evaporates."], None)
q("ws-014", B, 2, CS, "A kettle of water is boiling. What is the white mist at Y made of?", "Tiny drops of liquid water", [W("Water vapour coming out of the spout", "wrong-idea", "Water vapour is a gas that we cannot see."), W("Smoke from the burning heater", "wrong-idea", "The kettle only contains water."), W("Tiny pieces of ice", "wrong-idea", "The air above a kettle is too hot for ice.")], ["Water vapour cools in the air and condenses into tiny drops, which we see as mist."], KE)
q("ws-015", B, 3, RD, "The table shows the melting points and boiling points of four substances. Which substance is a liquid at 25 " + D + "?", "P", [W("Q", "wrong-reading", "25 " + D + " is below the melting point of Q, so Q is solid."), W("R", "wrong-reading", "25 " + D + " is above the boiling point of R, so R is a gas."), W("S", "wrong-reading", "25 " + D + " is below the melting point of S, so S is solid.")], ["A liquid is above its melting point and below its boiling point. 25 " + D + " is between -20 " + D + " and 80 " + D + "."], T1)
q("ws-016", B, 3, RD, "The table shows the melting points and boiling points of four substances. Which substance is a gas at 25 " + D + "?", "R", [W("P", "wrong-reading", "25 " + D + " is below the boiling point of P, so P is a liquid."), W("Q", "wrong-reading", "25 " + D + " is below the melting point of Q, so Q is solid."), W("S", "wrong-reading", "25 " + D + " is below the melting point of S, so S is solid.")], ["A gas is above its boiling point. 25 " + D + " is above -10 " + D + "."], T1)
q("ws-017", B, 4, CS, "Ice at -5 " + D + " is heated in a beaker. What is the first change seen when the ice reaches 0 " + D + "?", "The ice begins to melt", [W("The water begins to boil", "wrong-order", "Boiling happens much later, at 100 " + D + "."), W("The water begins to freeze", "reversed", "Heating cannot make water freeze."), W("The ice turns into water vapour", "wrong-order", "Ice becomes liquid first.")], ["At 0 " + D + " the ice starts to melt."], None)
q("ws-018", B, 1, CS, "Which states of water can flow?", "Liquid water and water vapour", [W("Ice, which can be poured out", "wrong-state", "Ice keeps its shape and does not flow."), W("Ice and liquid water", "wrong-state", "Ice does not flow."), W("Water vapour only, since it spreads out", "wrong-state", "Liquid water can flow too.")], ["Liquids and gases can flow, but solids cannot."], None)
q("ws-019", B, 2, CS, "Water in an ice tray is put in a freezer and turns into ice. What happens to the water?", "It loses heat and freezes", [W("It gains heat and freezes", "reversed", "Water must lose heat to freeze."), W("It loses heat and melts", "mixed-up", "Melting is ice becoming water."), W("It gains heat and melts", "mixed-up", "The water is becoming ice, not melting.")], ["Water gives out heat to the cold freezer and becomes ice."], None)
q("ws-020", B, 2, CS, "A bathroom mirror becomes misty after a hot shower. Which change caused this?", "Water vapour condensing on the cool mirror", [W("Water on the mirror freezing into ice", "wrong-idea", "The mirror is not cold enough to make ice."), W("Water vapour boiling away on the mirror", "wrong-idea", "Boiling needs the water to gain heat."), W("Hot water melting on the mirror", "wrong-idea", "Melting is ice turning into water.")], ["Water vapour from the shower loses heat to the cool mirror and condenses into tiny droplets."], None)
q("ws-021", B, 1, CS, "Which state of water can be squeezed into a smaller space most easily?", "Water vapour", [W("Ice", "wrong-state", "A solid is hard to squeeze smaller."), W("Liquid water", "wrong-state", "A liquid is hard to squeeze smaller."), W("Ice and liquid water", "wrong-state", "Neither can be squeezed easily.")], ["A gas can be squeezed into a smaller space."], None)
q("ws-022", B, 3, CS, "The water in a beaker is bubbling and the thermometer reading is shown. What does the reading tell us?", "Water boils at this temperature", [W("Water melts at this temperature", "mixed-up", "Ice melts at 0 " + D + "."), W("Water freezes at this temperature", "mixed-up", "Water freezes at 0 " + D + "."), W("The water is not yet hot enough to boil", "wrong-reading", "The reading is at the boiling point.")], ["The reading is 100 " + D + ", the boiling point of water."], TH100)
q("ws-023", B, 1, CS, "Ice, liquid water and water vapour are ____.", "three states of the same substance", [W("three different kinds of substance", "wrong-idea", "They are all water."), W("one solid, one liquid and one liquid", "wrong-idea", "Ice is solid, water is liquid and vapour is a gas."), W("three kinds of liquid", "wrong-idea", "Only one of them is a liquid.")], ["They are the solid, liquid and gas states of water."], None)
q("ws-024", B, 2, CS, "Wet clothes dry on a clothes line. What has happened to the water in the clothes?", "It has changed into water vapour", [W("It has frozen into ice", "wrong-idea", "The clothes are not cold enough for ice."), W("It has disappeared completely", "wrong-idea", "Water does not vanish. It changes state."), W("It has changed into ice and then melted", "wrong-idea", "No ice forms when clothes dry in the air.")], ["The water in the clothes evaporates into the air."], None)
q("ws-025", B, 2, CS, "Which two letters in the diagram show changes in which water gains heat?", "P and R", [W("Q and S", "reversed", "Freezing and condensation need heat to be lost."), W("P and Q", "mixed-up", "Q is freezing, which needs heat to be lost."), W("R and S", "mixed-up", "S is condensation, which needs heat to be lost.")], ["Melting (P) and boiling or evaporation (R) both need heat to be gained."], ST("A"))

# ---------------- intermediate ----------------
q("ws-101", I, 2, CS, "Which two letters in the diagram show changes in which water loses heat?", "Q and S", [W("P and R", "reversed", "Those changes need heat to be gained."), W("P and Q", "mixed-up", "P is melting, which needs heat to be gained."), W("R and S", "mixed-up", "R is a change from liquid to gas, which needs heat to be gained.")], ["Freezing and condensation need heat to be lost. In this diagram they are S and Q."], ST("B"))
q("ws-102", I, 2, CS, "Wet washing dries on a sunny day. Which letter shows this change?", "R", [W("P", "mixed-up", "P is melting, which is ice becoming water."), W("Q", "mixed-up", "Q is freezing."), W("S", "mixed-up", "S is condensation.")], ["The water in the washing changes into water vapour, which is R."], ST("A"))
q("ws-103", I, 2, CS, "Droplets form on the outside of a cold glass. Which letter shows the change that makes them?", "P", [W("Q", "mixed-up", "Q is a liquid becoming a gas."), W("R", "mixed-up", "R is a liquid becoming ice."), W("S", "mixed-up", "S is ice becoming water.")], ["Water vapour changing to droplets is condensation, which is P in this diagram."], ST("C"))
q("ws-104", I, 2, CS, "Droplets form on the outside of a glass of iced water. Why does this happen?", "Water vapour in the air loses heat to the cold glass and condenses", [W("Water vapour in the air gains heat from the glass and condenses", "reversed", "Condensing needs heat to be lost."), W("Water from the ice seeps through the glass", "wrong-idea", "Glass does not let water through."), W("Cold from the ice goes through the glass and freezes the air", "wrong-idea", "Cold does not flow. Heat is lost from the air to the glass.")], ["Warm air next to the cold glass loses heat, so water vapour condenses into droplets."], GL)
q("ws-105", I, 2, CS, "A kettle of water is boiling. What is found in the clear gap X just above the spout?", "Water vapour", [W("Tiny drops of liquid water", "wrong-idea", "Drops would show up as mist."), W("Tiny pieces of ice", "wrong-idea", "It is too hot for ice."), W("Nothing at all", "wrong-idea", "Boiling water is turning into a gas that we cannot see.")], ["Water vapour is invisible, so the gap looks clear."], KE)
q("ws-106", I, 2, CS, "In the kettle, why is there a clear gap between the spout and the white mist at Y?", "The vapour only condenses after it has cooled in the air", [W("The water has not yet boiled near the spout", "wrong-idea", "The water is boiling because vapour is coming out."), W("Ice forms in the air away from the spout", "wrong-idea", "The mist is liquid drops, not ice."), W("The vapour changes into liquid before it leaves", "wrong-idea", "Condensation would wet the spout instead of leaving a gap.")], ["Hot vapour is invisible. It cools in the air and condenses into mist a little way out."], KE)
q("ws-107", I, 2, CS, "A cold lid is held over a pot of boiling water. Droplets form under the lid. Why?", "The rising vapour gives out heat to the lid and condenses", [W("The rising vapour takes in heat from the lid and condenses", "reversed", "Condensation needs heat to be lost."), W("Hot water boils on the lid and falls back as drops", "wrong-idea", "Boiling needs the water to gain heat, and the lid is cold."), W("The lid has tiny holes that let water out", "wrong-idea", "The droplets are on the underside, so they come from below.")], ["Water vapour rising from the pot meets the cold lid, loses heat and turns into liquid drops."], PL)
q("ws-108", I, 3, RD, "The table shows the melting points and boiling points of four substances. At 20 " + D + ", which substance is a gas?", "S", [W("P", "wrong-reading", "20 " + D + " is between -115 " + D + " and 78 " + D + ", so P is a liquid."), W("Q", "wrong-reading", "20 " + D + " is between -39 " + D + " and 357 " + D + ", so Q is a liquid."), W("R", "wrong-reading", "20 " + D + " is below the melting point of R, so R is a solid.")], ["20 " + D + " is above the boiling point of S (-183 " + D + "), so S is a gas."], T2)
q("ws-109", I, 3, RD, "The table shows the melting points and boiling points of four substances. Which substance is a liquid at 100 " + D + "?", "Q", [W("P", "wrong-reading", "100 " + D + " is above the boiling point of P, so P is a gas."), W("R", "wrong-reading", "100 " + D + " is below the melting point of R, so R is a solid."), W("S", "wrong-reading", "100 " + D + " is above the boiling point of S, so S is a gas.")], ["100 " + D + " is between -39 " + D + " and 357 " + D + ", so Q is a liquid."], T2)
q("ws-110", I, 3, CS, "A block of ice at 0 " + D + " is placed in a warm room. What happens to the temperature of the ice while it is melting?", "It stays at 0 " + D + " until all the ice has melted", [W("It rises steadily as the room is warm", "wrong-idea", "The temperature stays at the melting point until the ice is gone."), W("It falls below 0 " + D + " as the ice loses cold", "wrong-idea", "The ice gains heat from the room. It does not get colder."), W("It rises to 100 " + D + " at once", "wrong-idea", "Only boiling water reaches 100 " + D + ".")], ["The heat gained is used to melt the ice, so the temperature stays at 0 " + D + "."], None)
q("ws-111", I, 4, RD, "Ice in a beaker is heated steadily. The graph shows the temperature. Which part of the graph shows the ice melting?", "B", [W("A", "wrong-reading", "In A the ice is getting warmer but has not started to melt."), W("C", "wrong-reading", "In C the melting is over and the water is getting hotter."), W("D", "wrong-reading", "D is the flat part where the water boils.")], ["The first flat part, at 0 " + D + ", is the ice melting."], CV)
q("ws-112", I, 4, RD, "Ice in a beaker is heated steadily and its temperature is recorded as shown. Which part of the graph shows the water boiling?", "D", [W("B", "wrong-reading", "B is at 0 " + D + ", where ice melts."), W("C", "wrong-reading", "In C the temperature is still rising, so the water has not started to boil."), W("E", "wrong-reading", "In E the temperature is rising again, so boiling is finished.")], ["The second flat part, at 100 " + D + ", is boiling."], CV)
q("ws-113", I, 4, RD, "Ice in a beaker is heated steadily and its temperature is recorded as shown. In which state is the water during part C?", "Liquid water only", [W("Ice and liquid water", "wrong-reading", "That is part B, while the ice is melting."), W("Liquid water and water vapour", "wrong-reading", "That is part D, while the water boils."), W("Water vapour only", "wrong-reading", "That is part E, after all the water has boiled away.")], ["All the ice has melted and the water has not started to boil."], CV)
q("ws-114", I, 4, RD, "Ice in a beaker is heated steadily and its temperature is recorded as shown. Why does the temperature stay at 0 " + D + " in part B although the heater is still on?", "The heat gained is used to change ice into water", [W("The heater stops giving out heat for a while", "wrong-idea", "The heater is still on."), W("The ice loses heat as fast as it gains heat", "wrong-idea", "The ice is gaining heat all the time."), W("The thermometer cannot read above 0 " + D, "wrong-idea", "The same thermometer reads higher later.")], ["Heat is used up in changing the state, so the temperature does not rise until all the ice has melted."], CV)
q("ws-115", I, 3, RD, "Ice in a beaker is heated steadily and its temperature is recorded as shown. What is the boiling point of the water?", "100 " + D, [W("0 " + D, "wrong-reading", "0 " + D + " is where the first flat part is, which is melting."), W("112 " + D, "wrong-reading", "112 " + D + " is only the highest reading at the end."), W("20 " + D, "wrong-reading", "20 is a time in minutes, not a temperature.")], ["The temperature stays at 100 " + D + " in the second flat part."], CV)
q("ws-116", I, 4, CS, "Water in an open beaker is boiling on a stove. The thermometer stays at 100 " + D + " even though the flame is still on. What is the heat being used for?", "Changing liquid water into water vapour", [W("Making the water hotter than 100 " + D, "wrong-idea", "The reading is not rising."), W("Turning water vapour back into liquid water", "reversed", "That change gives out heat."), W("Making the beaker lose mass", "wrong-idea", "The heat is used to change the water's state.")], ["The heat is used to change water into water vapour, not to raise the temperature."], None)
q("ws-117", I, 2, CS, "On a cool morning the inside of a bus window is covered with tiny drops. What are the drops?", "Liquid water formed from water vapour in the passengers' breath", [W("Ice that has melted from the window glass", "wrong-idea", "The glass is not made of ice."), W("Water vapour that has become visible", "wrong-idea", "Water vapour cannot be seen. The drops are liquid."), W("Water that has leaked through the glass from outside", "wrong-idea", "The drops form on the inside, from the warm moist air.")], ["Water vapour from breath cools on the cold glass and condenses into liquid drops."], None)
q("ws-118", I, 2, CS, "Which statement about boiling and evaporation is correct?", "Evaporation happens only at the surface, but boiling happens throughout the water", [W("Boiling happens only at the surface, but evaporation happens throughout the water", "reversed", "Bubbles form inside boiling water."), W("Both happen only when water is at 100 " + D, "wrong-idea", "Evaporation also happens at lower temperatures."), W("Evaporation needs the water to lose heat", "wrong-idea", "Both changes need heat to be gained.")], ["Evaporation takes place at the surface at any temperature. Boiling takes place throughout the liquid at 100 " + D + "."], None)
q("ws-119", I, 1, RD, "The table describes water in three forms X, Y and Z. Which one is water vapour?", "Z", [W("X", "wrong-reading", "X has a fixed shape and a fixed volume, so it is ice."), W("Y", "wrong-reading", "Y takes any shape but keeps its volume, so it is liquid water."), W("Both X and Y", "wrong-reading", "Neither of them spreads out to fill a space.")], ["Water vapour has neither a fixed shape nor a fixed volume."], T3)
q("ws-120", I, 2, CS, "Which of the following changes needs water to lose heat?", "Water vapour forming drops on a cold window", [W("A wet floor drying in the hot Sun", "reversed", "Drying means water gains heat and evaporates."), W("An ice cube turning into water in a cup", "reversed", "Melting needs heat to be gained."), W("Water bubbling away in a hot pot", "reversed", "Boiling needs heat to be gained.")], ["Condensation is the only change here in which water loses heat."], None)
q("ws-121", I, 3, CS, "Which of the following describes boiling?", "Liquid water changes to water vapour throughout the liquid at 100 " + D, [W("Ice changes to liquid water throughout the block at 100 " + D, "mixed-up", "That describes melting, which happens at 0 " + D + "."), W("Water vapour changes to liquid water on cooling at 100 " + D, "mixed-up", "That is condensation."), W("Liquid water changes to ice throughout the liquid at 0 " + D, "mixed-up", "That is freezing.")], ["Boiling is the change from liquid to gas, happening in the whole liquid at 100 " + D + "."], None)
q("ws-122", I, 3, CS, "A beaker of water at 15 " + D + " is put in a freezer. The thermometer shows the same reading for a long time while the water turns into ice. What is the reading?", "0 " + D, [W("-18 " + D, "wrong-idea", "That is the freezer's temperature, reached only after all the water has frozen."), W("15 " + D, "wrong-idea", "The water has cooled well below its starting temperature."), W("100 " + D, "mixed-up", "That is the boiling point.")], ["Water freezes at 0 " + D + ", and its temperature stays there until all of it is ice."], None)
q("ws-123", I, 1, CS, "A student pours 200 mL of water from a jug into a tall glass, and then into a wide bowl. Which statement is correct?", "The shape of the water changes but its volume stays at 200 mL", [W("Both the shape and the volume of the water change", "wrong-idea", "The amount of water stays the same."), W("The shape of the water stays the same but its volume changes", "reversed", "Liquid water takes the shape of its container."), W("Neither the shape nor the volume of the water changes", "wrong-idea", "The shape follows the container.")], ["A liquid takes the shape of its container and keeps its volume."], None)
q("ws-124", I, 2, CS, "On a hot day an ice lolly melts and drips. What happens to heat?", "The lolly gains heat from the air", [W("The lolly loses heat to the air", "reversed", "Melting needs heat to be gained."), W("The air gains heat from the lolly", "reversed", "Heat flows from the hot air to the cold lolly."), W("No heat moves, since the lolly is being cold", "wrong-idea", "A difference in temperature always makes heat flow.")], ["Heat flows from the warm air to the cold lolly, which melts."], None)
q("ws-125", I, 3, CS, "The temperature at which pure liquid water changes into a gas is called the ____ point.", "boiling", [W("melting", "mixed-up", "Melting is the change from solid to liquid."), W("freezing", "mixed-up", "Freezing is the change from liquid to solid."), W("condensing", "mixed-up", "Condensation is the change from gas to liquid.")], ["Water changes to a gas at its boiling point, 100 " + D + "."], None)

